-- Scenario: 智能报价 → 订单 → 排产全链路

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- <<kind>> 客户 (PI: customer_no)
CREATE TABLE customer (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    customer_no VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> 产品 (PI: sku)
CREATE TABLE product (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    sku VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> 员工 (PI: employee_no)
CREATE TABLE employee (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    employee_no VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> CNC 机床 (PI: machine_code)
CREATE TABLE cncmachine (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    machine_code VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> 材料 (PI: material_code)
CREATE TABLE material (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    material_code VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> 报价单 (PI: quote_no)
CREATE TABLE quotation (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    quote_no VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> 销售订单 (PI: order_no)
CREATE TABLE sales_order (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    order_no VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> 排产任务 (PI: task_no)
CREATE TABLE production_task (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    task_no VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> 工艺路线 (PI: route_id + version)
CREATE TABLE process_route (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    route_id VARCHAR(64) UNIQUE NOT NULL,
    version VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> CNC 工序 (PI: process_id)
CREATE TABLE cncprocess (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    process_id VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<kind>> 工作中心 (PI: wc_code)
CREATE TABLE work_center (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    wc_code VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<mode>> 客户信用等级 (依附 customer)
CREATE TABLE customer_credit_level (
    customer_id UUID PRIMARY KEY REFERENCES customer(id),
    value INT
);

-- <<mode>> 机床状态 (依附 cncmachine)
CREATE TABLE machine_status (
    cncmachine_id UUID PRIMARY KEY REFERENCES cncmachine(id),
    value VARCHAR(32) CHECK (value IN ('idle', 'busy', 'maintenance', 'breakdown'))
);

-- <<relator>> 询价关系
CREATE TABLE inquiry_relator (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    customer_id UUID REFERENCES customer(id),
    sales_rep_id UUID REFERENCES sales_rep(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<relator>> 报价关系
CREATE TABLE quotation_relator (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    customer_id UUID REFERENCES customer(id),
    quoter_id UUID REFERENCES quoter(id),
    quotation_id UUID REFERENCES quotation(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<relator>> 审批关系
CREATE TABLE approval_relator (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    quotation_id UUID REFERENCES quotation(id),
    approver_id UUID REFERENCES approver(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<relator>> 报价项关系
CREATE TABLE quote_item_relator (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    quotation_id UUID REFERENCES quotation(id),
    product_id UUID REFERENCES product(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<relator>> 订单关系
CREATE TABLE sales_order_relator (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    quotation_id UUID REFERENCES quotation(id),
    order_converter_id UUID REFERENCES order_converter(id),
    sales_order_id UUID REFERENCES sales_order(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<relator>> 排产关系
CREATE TABLE schedule_relator (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    sales_order_id UUID REFERENCES sales_order(id),
    planner_id UUID REFERENCES planner(id),
    production_task_id UUID REFERENCES production_task(id),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- <<phase>> of quotation
ALTER TABLE quotation ADD COLUMN status VARCHAR(32)
    DEFAULT 'Draft'
    CHECK (status IN ('Draft', 'Pricing', 'PendingApproval', 'Approved', 'Rejected', 'Sent', 'Expired', 'Accepted'));

-- <<phase>> of sales_order
ALTER TABLE sales_order ADD COLUMN status VARCHAR(32)
    DEFAULT 'Draft'
    CHECK (status IN ('Draft', 'Confirmed', 'InProduction', 'Shipped', 'Closed'));

-- <<phase>> of production_task
ALTER TABLE production_task ADD COLUMN status VARCHAR(32)
    DEFAULT 'Queued'
    CHECK (status IN ('Queued', 'Released', 'InProgress', 'Completed', 'Aborted'));

ALTER TABLE product ADD COLUMN unit_price NUMERIC(18,4);
ALTER TABLE quote_item_relator ADD COLUMN quantity INT;
ALTER TABLE sales_order_relator ADD COLUMN quantity INT;
ALTER TABLE quotation ADD COLUMN discount_rate NUMERIC(18,4);
ALTER TABLE quotation ADD COLUMN validity_days INT;
ALTER TABLE quotation ADD COLUMN total_amount NUMERIC(18,4);
ALTER TABLE sales_order ADD COLUMN total_amount NUMERIC(18,4);
ALTER TABLE sales_order ADD COLUMN delivery_date DATE;
ALTER TABLE cncprocess ADD COLUMN cycle_time INT;
ALTER TABLE cncmachine ADD COLUMN machine_hour_rate NUMERIC(18,4);
ALTER TABLE production_task ADD COLUMN planned_start TIMESTAMPTZ;
ALTER TABLE production_task ADD COLUMN planned_end TIMESTAMPTZ;

-- ===================== STATE MACHINE TRIGGERS =====================
CREATE OR REPLACE FUNCTION tr_quotation_phase_guard() RETURNS TRIGGER AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF OLD.status = 'Draft' AND NEW.status = 'Pricing' THEN RETURN NEW; END IF;
  IF OLD.status = 'Pricing' AND NEW.status = 'PendingApproval' THEN RETURN NEW; END IF;
  IF OLD.status = 'PendingApproval' AND NEW.status = 'Approved' THEN RETURN NEW; END IF;
  IF OLD.status = 'PendingApproval' AND NEW.status = 'Rejected' THEN RETURN NEW; END IF;
  IF OLD.status = 'Approved' AND NEW.status = 'Sent' THEN RETURN NEW; END IF;
  IF OLD.status = 'Sent' AND NEW.status = 'Expired' THEN RETURN NEW; END IF;
  IF OLD.status = 'Sent' AND NEW.status = 'Accepted' THEN RETURN NEW; END IF;
  RAISE EXCEPTION '非法状态转移: % → %', OLD.status, NEW.status;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER tr_quotation_phase_guard
  BEFORE UPDATE ON quotation
  FOR EACH ROW EXECUTE FUNCTION tr_quotation_phase_guard();

CREATE OR REPLACE FUNCTION tr_sales_order_phase_guard() RETURNS TRIGGER AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF OLD.status = 'Draft' AND NEW.status = 'Confirmed' THEN RETURN NEW; END IF;
  IF OLD.status = 'Confirmed' AND NEW.status = 'InProduction' THEN RETURN NEW; END IF;
  IF OLD.status = 'InProduction' AND NEW.status = 'Shipped' THEN RETURN NEW; END IF;
  IF OLD.status = 'Shipped' AND NEW.status = 'Closed' THEN RETURN NEW; END IF;
  RAISE EXCEPTION '非法状态转移: % → %', OLD.status, NEW.status;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER tr_sales_order_phase_guard
  BEFORE UPDATE ON sales_order
  FOR EACH ROW EXECUTE FUNCTION tr_sales_order_phase_guard();

CREATE OR REPLACE FUNCTION tr_production_task_phase_guard() RETURNS TRIGGER AS $$
BEGIN
  IF OLD.status = NEW.status THEN RETURN NEW; END IF;
  IF OLD.status = 'Queued' AND NEW.status = 'Released' THEN RETURN NEW; END IF;
  IF OLD.status = 'Released' AND NEW.status = 'InProgress' THEN RETURN NEW; END IF;
  IF OLD.status = 'InProgress' AND NEW.status = 'Completed' THEN RETURN NEW; END IF;
  IF OLD.status = 'InProgress' AND NEW.status = 'Aborted' THEN RETURN NEW; END IF;
  RAISE EXCEPTION '非法状态转移: % → %', OLD.status, NEW.status;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER tr_production_task_phase_guard
  BEFORE UPDATE ON production_task
  FOR EACH ROW EXECUTE FUNCTION tr_production_task_phase_guard();
